-- 0004_people.sql
-- Students, guardians, teachers, teaching assignments, enrollments, uploads.

-- Business identifiers are generated by sequence and can never be edited,
-- not even by an admin (BRD 6.2 / 7).
CREATE FUNCTION forbid_immutable_change() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  col TEXT := TG_ARGV[0];
BEGIN
  IF (to_jsonb(OLD) ->> col) IS DISTINCT FROM (to_jsonb(NEW) ->> col) THEN
    RAISE EXCEPTION 'column % is immutable once set', col USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------

CREATE TABLE students (
  id              INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  admission_id    TEXT NOT NULL DEFAULT ('VVS-' || lpad(nextval('admission_id_seq')::text, 6, '0')),
  user_id         INTEGER UNIQUE REFERENCES users (id) ON DELETE SET NULL,
  first_name      TEXT NOT NULL,
  last_name       TEXT NOT NULL,
  date_of_birth   DATE NOT NULL,
  gender          TEXT NOT NULL CHECK (gender IN ('male', 'female', 'other')),
  blood_group     TEXT,
  photo_path      TEXT,
  admission_date  DATE NOT NULL,
  previous_school TEXT,
  status          student_status NOT NULL DEFAULT 'new_admission',
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at      TIMESTAMPTZ,
  CONSTRAINT students_admission_id_format CHECK (admission_id ~ '^VVS-\d{6,}$'),
  CONSTRAINT students_dob_sane CHECK (date_of_birth > DATE '1990-01-01')
);

CREATE UNIQUE INDEX students_admission_id_key ON students (admission_id);
CREATE INDEX students_status_idx ON students (status) WHERE deleted_at IS NULL;
CREATE INDEX students_name_trgm_idx ON students
  USING gin ((lower(first_name || ' ' || last_name)) gin_trgm_ops);
CREATE INDEX students_admission_id_trgm_idx ON students USING gin (admission_id gin_trgm_ops);

CREATE TRIGGER students_set_updated_at BEFORE UPDATE ON students
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER students_admission_id_immutable BEFORE UPDATE ON students
  FOR EACH ROW EXECUTE FUNCTION forbid_immutable_change('admission_id');

-- ---------------------------------------------------------------------------

CREATE TABLE parents (
  id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id      INTEGER UNIQUE REFERENCES users (id) ON DELETE SET NULL,
  full_name    TEXT NOT NULL,
  mobile       TEXT NOT NULL,
  email        TEXT,
  occupation   TEXT,
  address_line TEXT,
  city         TEXT,
  state        TEXT,
  pincode      TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at   TIMESTAMPTZ
);

CREATE INDEX parents_mobile_idx ON parents (mobile);
CREATE INDEX parents_name_trgm_idx ON parents USING gin (lower(full_name) gin_trgm_ops);

CREATE TRIGGER parents_set_updated_at BEFORE UPDATE ON parents
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One parent (family account) can be linked to several children.
CREATE TABLE student_parents (
  student_id   INTEGER NOT NULL REFERENCES students (id) ON DELETE CASCADE,
  parent_id    INTEGER NOT NULL REFERENCES parents (id) ON DELETE CASCADE,
  relationship TEXT NOT NULL CHECK (relationship IN ('father', 'mother', 'guardian')),
  is_primary   BOOLEAN NOT NULL DEFAULT FALSE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (student_id, parent_id)
);

CREATE INDEX student_parents_parent_idx ON student_parents (parent_id);

-- ---------------------------------------------------------------------------

CREATE TABLE teachers (
  id               INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  employee_id      TEXT NOT NULL DEFAULT ('VVT-' || lpad(nextval('employee_id_seq')::text, 4, '0')),
  user_id          INTEGER UNIQUE REFERENCES users (id) ON DELETE SET NULL,
  first_name       TEXT NOT NULL,
  last_name        TEXT NOT NULL,
  gender           TEXT NOT NULL CHECK (gender IN ('male', 'female', 'other')),
  date_of_birth    DATE,
  photo_path       TEXT,
  mobile           TEXT NOT NULL,
  email            TEXT,
  address          TEXT,
  qualification    TEXT,
  experience_years NUMERIC(4, 1) CHECK (experience_years >= 0),
  joining_date     DATE NOT NULL,
  status           teacher_status NOT NULL DEFAULT 'active',
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at       TIMESTAMPTZ,
  CONSTRAINT teachers_employee_id_format CHECK (employee_id ~ '^VVT-\d{4,}$')
);

CREATE UNIQUE INDEX teachers_employee_id_key ON teachers (employee_id);
CREATE INDEX teachers_status_idx ON teachers (status) WHERE deleted_at IS NULL;
CREATE INDEX teachers_name_trgm_idx ON teachers
  USING gin ((lower(first_name || ' ' || last_name)) gin_trgm_ops);

CREATE TRIGGER teachers_set_updated_at BEFORE UPDATE ON teachers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER teachers_employee_id_immutable BEFORE UPDATE ON teachers
  FOR EACH ROW EXECUTE FUNCTION forbid_immutable_change('employee_id');

-- ---------------------------------------------------------------------------
-- A section has exactly one class teacher per academic year, and a teacher can
-- be class teacher of at most one section per academic year.
-- ---------------------------------------------------------------------------

CREATE TABLE class_teachers (
  id               INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  academic_year_id INTEGER NOT NULL REFERENCES academic_years (id) ON DELETE RESTRICT,
  section_id       INTEGER NOT NULL REFERENCES sections (id) ON DELETE CASCADE,
  teacher_id       INTEGER NOT NULL REFERENCES teachers (id) ON DELETE RESTRICT,
  effective_from   DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT class_teachers_one_per_section UNIQUE (academic_year_id, section_id),
  CONSTRAINT class_teachers_one_section_per_teacher UNIQUE (academic_year_id, teacher_id)
);

CREATE INDEX class_teachers_teacher_idx ON class_teachers (teacher_id);

CREATE TRIGGER class_teachers_set_updated_at BEFORE UPDATE ON class_teachers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Which teacher teaches which subject to which class in a given year.
CREATE TABLE teacher_subjects (
  id               INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  academic_year_id INTEGER NOT NULL REFERENCES academic_years (id) ON DELETE CASCADE,
  teacher_id       INTEGER NOT NULL REFERENCES teachers (id) ON DELETE CASCADE,
  class_id         INTEGER NOT NULL REFERENCES classes (id) ON DELETE CASCADE,
  subject_id       INTEGER NOT NULL REFERENCES subjects (id) ON DELETE CASCADE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT teacher_subjects_unique UNIQUE (academic_year_id, teacher_id, class_id, subject_id)
);

CREATE INDEX teacher_subjects_lookup_idx ON teacher_subjects (academic_year_id, class_id, subject_id);

-- ---------------------------------------------------------------------------
-- Enrollment: which class+section a student is in for one academic year.
-- Class never lives on the student row — it changes every year.
-- ---------------------------------------------------------------------------

CREATE TABLE enrollments (
  id                        INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id                INTEGER NOT NULL REFERENCES students (id) ON DELETE CASCADE,
  academic_year_id          INTEGER NOT NULL REFERENCES academic_years (id) ON DELETE RESTRICT,
  class_id                  INTEGER NOT NULL REFERENCES classes (id) ON DELETE RESTRICT,
  section_id                INTEGER NOT NULL REFERENCES sections (id) ON DELETE RESTRICT,
  roll_no                   SMALLINT,
  status                    enrollment_status NOT NULL DEFAULT 'active',
  promoted_from_enrollment_id INTEGER REFERENCES enrollments (id) ON DELETE SET NULL,
  created_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT enrollments_one_per_year UNIQUE (student_id, academic_year_id)
);

CREATE INDEX enrollments_cohort_idx ON enrollments (academic_year_id, class_id, section_id);
CREATE INDEX enrollments_student_idx ON enrollments (student_id);

CREATE TRIGGER enrollments_set_updated_at BEFORE UPDATE ON enrollments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------

CREATE TABLE student_status_history (
  id               INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id       INTEGER NOT NULL REFERENCES students (id) ON DELETE CASCADE,
  academic_year_id INTEGER REFERENCES academic_years (id) ON DELETE SET NULL,
  from_status      student_status,
  to_status        student_status NOT NULL,
  effective_date   DATE NOT NULL,
  remarks          TEXT,
  changed_by       INTEGER REFERENCES users (id) ON DELETE SET NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX student_status_history_student_idx ON student_status_history (student_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- Uploaded files. The row records metadata only; bytes live on disk under
-- UPLOAD_DIR/<owner_type>/<owner_id>/<random>-<safe-name>.
-- ---------------------------------------------------------------------------

CREATE TABLE documents (
  id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  owner_type   TEXT NOT NULL CHECK (owner_type IN ('student', 'announcement', 'assignment', 'event')),
  owner_id     INTEGER NOT NULL,
  doc_type     TEXT,
  file_name    TEXT NOT NULL,
  file_path    TEXT NOT NULL,
  mime_type    TEXT NOT NULL,
  size_bytes   INTEGER NOT NULL CHECK (size_bytes > 0),
  uploaded_by  INTEGER REFERENCES users (id) ON DELETE SET NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at   TIMESTAMPTZ
);

CREATE INDEX documents_owner_idx ON documents (owner_type, owner_id) WHERE deleted_at IS NULL;
